      window.__swRegistration = navigator.serviceWorker
        ? navigator.serviceWorker
            .register("px0hh8.js")
            .then(function (reg) {
              // If this document loaded WITHOUT a controlling service worker,
              // the proxy sits on a 45s control-timeout before falling back.
              // That happens on a hard reload (the browser bypasses the SW for
              // the top document) and can happen on a first visit before the
              // worker claims. Grab control fast: give claim a short grace
              // window, and if we're still uncontrolled, reload ONCE (guarded
              // by sessionStorage so we can never loop) to pick up the worker.
              if (navigator.serviceWorker.controller) {
                sessionStorage.removeItem("__sw_reload");
                return reg;
              }
              if (sessionStorage.getItem("__sw_reload")) return reg;
              navigator.serviceWorker.ready.then(function () {
                if (navigator.serviceWorker.controller) return;
                var settled = false;
                var onCtrl = function () {
                  settled = true;
                  navigator.serviceWorker.removeEventListener(
                    "controllerchange",
                    onCtrl
                  );
                };
                navigator.serviceWorker.addEventListener(
                  "controllerchange",
                  onCtrl
                );
                setTimeout(function () {
                  navigator.serviceWorker.removeEventListener(
                    "controllerchange",
                    onCtrl
                  );
                  if (!settled && !navigator.serviceWorker.controller) {
                    sessionStorage.setItem("__sw_reload", "1");
                    location.reload();
                  }
                }, 1200);
              });
              return reg;
            })
            .catch(function (err) {
              console.error("[sw] registration failed:", err);
              return null;
            })
        : Promise.resolve(null);

/**/

